CREATE INDEX IF NOT EXISTS idx_inv_orders_site_status ON inventory_orders(site_id, status);
CREATE INDEX IF NOT EXISTS idx_inv_order_items_order ON inventory_order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_inv_order_items_barcode ON inventory_order_items(barcode);
CREATE INDEX IF NOT EXISTS idx_inv_receipts_site ON inventory_receipts(site_id, scanned_at DESC);
CREATE INDEX IF NOT EXISTS idx_inv_stock_low ON inventory_stock(site_id) WHERE on_hand <= threshold;
CREATE INDEX IF NOT EXISTS idx_inv_issues_site ON inventory_issues(site_id, issued_at DESC);
CREATE INDEX IF NOT EXISTS idx_inv_reorder_open ON inventory_reorder_requests(site_id, status);
CREATE INDEX IF NOT EXISTS idx_inv_mismatch_site ON inventory_mismatch_flags(site_id, flagged_at DESC);
CREATE INDEX IF NOT EXISTS idx_inv_corrections_site ON inventory_stock_corrections(site_id, corrected_at DESC);
CREATE INDEX IF NOT EXISTS idx_inv_corrections_barcode ON inventory_stock_corrections(site_id, barcode);

-- Cache for normalized product names so repeat hits skip the LLM.
-- Keyed by (site_id, lower(raw_name)) — site-scoped because two
-- sites might canonicalise the same raw input differently (e.g.
-- regional brand variations).
CREATE TABLE IF NOT EXISTS inventory_name_aliases (
  site_id TEXT NOT NULL,
  raw_name TEXT NOT NULL,
  canonical_name TEXT NOT NULL,
  language TEXT,
  confidence REAL NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (site_id, raw_name)
);

-- ─── Canonical Product Catalog ───────────────────────────────
-- Source-of-truth product list. Admin-created only. Guards pick
-- from this list — they never type free-text product names.
-- Product identity lives here; barcodes and vendor-name aliases
-- are secondary mappings in their own tables.

CREATE TABLE IF NOT EXISTS canonical_products (
  product_id TEXT PRIMARY KEY,
  site_id TEXT NOT NULL,
  canonical_name TEXT NOT NULL,
  category TEXT,
  hsn_code TEXT,
  unit TEXT NOT NULL DEFAULT 'pcs',
  pack_size REAL NOT NULL DEFAULT 1,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(site_id, canonical_name)
);

CREATE INDEX IF NOT EXISTS idx_canonical_products_site ON canonical_products(site_id);
CREATE INDEX IF NOT EXISTS idx_canonical_products_hsn ON canonical_products(site_id, hsn_code);

-- Many-to-one mapping: vendor bill names → canonical product.
-- Each vendor may write the same product differently. HSN is kept
-- for context-dependent disambiguation (e.g. "Biscuit" + HSN 1905
-- means Parle-G, not a generic term).
CREATE TABLE IF NOT EXISTS product_aliases (
  id TEXT PRIMARY KEY,
  site_id TEXT NOT NULL,
  raw_name TEXT NOT NULL,
  product_id TEXT NOT NULL REFERENCES canonical_products(product_id) ON DELETE CASCADE,
  hsn_code TEXT,
  vendor_name TEXT,
  confidence REAL NOT NULL DEFAULT 1.0,
  source TEXT NOT NULL DEFAULT 'admin_manual',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Same raw_name can map differently per HSN. Expression-based unique
-- index because Postgres rejects COALESCE inside a UNIQUE constraint.
CREATE UNIQUE INDEX IF NOT EXISTS uq_product_aliases_raw_hsn
  ON product_aliases (site_id, raw_name, COALESCE(hsn_code, ''));
CREATE INDEX IF NOT EXISTS idx_product_aliases_lookup ON product_aliases(site_id, raw_name);
CREATE INDEX IF NOT EXISTS idx_product_aliases_product ON product_aliases(product_id);

-- Many-to-one mapping: physical barcodes → canonical product.
-- Learned automatically when a guard scans a barcode and picks
-- a product from the catalog, or entered manually by admin.
CREATE TABLE IF NOT EXISTS product_barcodes (
  barcode TEXT NOT NULL,
  site_id TEXT NOT NULL,
  product_id TEXT NOT NULL REFERENCES canonical_products(product_id) ON DELETE CASCADE,
  learned_from TEXT NOT NULL DEFAULT 'scan',
  learned_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (site_id, barcode)
);

CREATE INDEX IF NOT EXISTS idx_product_barcodes_product ON product_barcodes(product_id);

-- Bill items that couldn't be auto-matched to a canonical product.
-- Admin resolves these from the dashboard, which teaches the alias
-- cache for future bills.
CREATE TABLE IF NOT EXISTS unresolved_bill_items (
  id TEXT PRIMARY KEY,
  site_id TEXT NOT NULL,
  order_id TEXT REFERENCES inventory_orders(id) ON DELETE CASCADE,
  bill_item_name TEXT NOT NULL,
  hsn_code TEXT,
  qty REAL NOT NULL,
  unit_rate REAL,
  line_value REAL,
  status TEXT NOT NULL DEFAULT 'pending',
  resolved_product_id TEXT REFERENCES canonical_products(product_id),
  resolved_by TEXT,
  resolved_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_unresolved_bill_items_site ON unresolved_bill_items(site_id, status);

-- Unit value (pack size) captured at registration time. Optional
-- — older rows stay NULL; the field-app form lets the guard skip it.
ALTER TABLE inventory_products ADD COLUMN IF NOT EXISTS pack_size REAL;

-- Extend inventory_orders with bill metadata
ALTER TABLE inventory_orders ADD COLUMN IF NOT EXISTS bill_number TEXT;
ALTER TABLE inventory_orders ADD COLUMN IF NOT EXISTS bill_date DATE;
ALTER TABLE inventory_orders ADD COLUMN IF NOT EXISTS bill_photo_url TEXT;
ALTER TABLE inventory_orders ADD COLUMN IF NOT EXISTS grand_total REAL;

-- Extend inventory_order_items with canonical product linkage + bill audit trail
ALTER TABLE inventory_order_items ADD COLUMN IF NOT EXISTS product_id TEXT;
ALTER TABLE inventory_order_items ADD COLUMN IF NOT EXISTS bill_item_name TEXT;
ALTER TABLE inventory_order_items ADD COLUMN IF NOT EXISTS hsn_code TEXT;
ALTER TABLE inventory_order_items ADD COLUMN IF NOT EXISTS unit_rate REAL;
ALTER TABLE inventory_order_items ADD COLUMN IF NOT EXISTS line_value REAL;
ALTER TABLE inventory_order_items ADD COLUMN IF NOT EXISTS match_method TEXT;
ALTER TABLE inventory_order_items ADD COLUMN IF NOT EXISTS match_confidence REAL;

CREATE INDEX IF NOT EXISTS idx_inv_order_items_product ON inventory_order_items(product_id);

-- Receipt-level linkage to canonical product + expiry. Powers the
-- compliance log (date-wise audit trail of every received item).
ALTER TABLE inventory_receipts ADD COLUMN IF NOT EXISTS product_id TEXT;
ALTER TABLE inventory_receipts ADD COLUMN IF NOT EXISTS expiry_date DATE;
CREATE INDEX IF NOT EXISTS idx_inv_receipts_product ON inventory_receipts(product_id);

-- Relax receipt → order FK so admins can delete an order without
-- hitting "violates foreign key constraint". Receipts are an audit
-- trail and should survive their order being removed (e.g. duplicate
-- bill upload), just with order_id / order_item_id set NULL.
DO $$ BEGIN
  ALTER TABLE inventory_receipts DROP CONSTRAINT IF EXISTS inventory_receipts_order_id_fkey;
  ALTER TABLE inventory_receipts
    ADD CONSTRAINT inventory_receipts_order_id_fkey
    FOREIGN KEY (order_id) REFERENCES inventory_orders(id) ON DELETE SET NULL;
  ALTER TABLE inventory_receipts DROP CONSTRAINT IF EXISTS inventory_receipts_order_item_id_fkey;
  ALTER TABLE inventory_receipts
    ADD CONSTRAINT inventory_receipts_order_item_id_fkey
    FOREIGN KEY (order_item_id) REFERENCES inventory_order_items(id) ON DELETE SET NULL;
  -- mismatch_flags.order_item_id → cascade-delete of order_items
  -- would otherwise leave dangling references and block the order
  -- delete. Mirror the SET NULL behaviour.
  ALTER TABLE inventory_mismatch_flags DROP CONSTRAINT IF EXISTS inventory_mismatch_flags_order_item_id_fkey;
  ALTER TABLE inventory_mismatch_flags
    ADD CONSTRAINT inventory_mismatch_flags_order_item_id_fkey
    FOREIGN KEY (order_item_id) REFERENCES inventory_order_items(id) ON DELETE SET NULL;
  ALTER TABLE inventory_mismatch_flags DROP CONSTRAINT IF EXISTS inventory_mismatch_flags_receipt_id_fkey;
  ALTER TABLE inventory_mismatch_flags
    ADD CONSTRAINT inventory_mismatch_flags_receipt_id_fkey
    FOREIGN KEY (receipt_id) REFERENCES inventory_receipts(id) ON DELETE SET NULL;
EXCEPTION WHEN others THEN
  -- ignore; constraint may not exist on first migration

      NULL;
    END $$;

    -- Per-site key/value settings for the inventory plugin. Used today
    -- for the attached Google Sheets spreadsheet id; future settings
    -- (default category, alert thresholds, etc.) live here too.
    CREATE TABLE IF NOT EXISTS inventory_settings (
      site_id TEXT NOT NULL,
      key TEXT NOT NULL,
      value TEXT,
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      PRIMARY KEY (site_id, key)
    );

    -- ─── Cafeteria ordering plugin ───────────────────────────────
    -- Telegram Mini App surface for ops staff taking employee food
    -- orders. Kept separate from inventory procurement orders.

    CREATE TABLE IF NOT EXISTS cafeteria_menu_items (
      id TEXT PRIMARY KEY,
      site_id TEXT NOT NULL DEFAULT 'default',
      name TEXT NOT NULL,
      category TEXT,
      price_cents INTEGER NOT NULL DEFAULT 0,
      is_available BOOLEAN NOT NULL DEFAULT true,
      sort_order INTEGER NOT NULL DEFAULT 100,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );

    CREATE TABLE IF NOT EXISTS cafeteria_orders (
      id TEXT PRIMARY KEY,
      site_id TEXT NOT NULL DEFAULT 'default',
      employee_name TEXT NOT NULL,
      employee_identifier TEXT,
      employee_staff_id TEXT,
      taken_by_telegram_id TEXT,
      taken_by_name TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'placed',
      notes TEXT,
      total_cents INTEGER NOT NULL DEFAULT 0,
      kitchen_channel_id TEXT,
      kitchen_message_id TEXT,
      kitchen_cancel_message_id TEXT,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );
    ALTER TABLE cafeteria_orders ADD COLUMN IF NOT EXISTS employee_staff_id TEXT;
    ALTER TABLE cafeteria_orders ADD COLUMN IF NOT EXISTS kitchen_channel_id TEXT;
    ALTER TABLE cafeteria_orders ADD COLUMN IF NOT EXISTS kitchen_message_id TEXT;
    ALTER TABLE cafeteria_orders ADD COLUMN IF NOT EXISTS kitchen_cancel_message_id TEXT;

    CREATE TABLE IF NOT EXISTS cafeteria_order_items (
      id TEXT PRIMARY KEY,
      order_id TEXT NOT NULL REFERENCES cafeteria_orders(id) ON DELETE CASCADE,
      menu_item_id TEXT REFERENCES cafeteria_menu_items(id),
      name TEXT NOT NULL,
      quantity INTEGER NOT NULL,
      unit_price_cents INTEGER NOT NULL DEFAULT 0,
      notes TEXT,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );

    CREATE INDEX IF NOT EXISTS idx_cafeteria_menu_site ON cafeteria_menu_items(site_id, is_available, sort_order);
    CREATE INDEX IF NOT EXISTS idx_cafeteria_orders_site_status ON cafeteria_orders(site_id, status, created_at DESC);
    CREATE INDEX IF NOT EXISTS idx_cafeteria_orders_created ON cafeteria_orders(created_at DESC);
    CREATE INDEX IF NOT EXISTS idx_cafeteria_order_items_order ON cafeteria_order_items(order_id);
  `;
}

