1199	export type CanonicalProduct = {
1200	  product_id: string;
1201	  site_id: string;
1202	  canonical_name: string;
1203	  category: string | null;
1204	  hsn_code: string | null;
1205	  unit: string;
1206	  pack_size: number;
1207	  created_by: string | null;
1208	  created_at: string;
1209	  updated_at: string;
1210	  /** True if any barcode is already mapped to this product. Populated by
1211	   *  list queries; the field-app's register-new-barcode flow uses this to
1212	   *  hide products that are already taken (one barcode per product, for
1213	   *  now). Single-row lookups leave it undefined. */
1214	  has_barcode?: boolean;
1215	  /** Most-recently learned real barcode mapped to this product on the
1216	   *  server, or null if none. Lets the field-app skip a round-trip when
1217	   *  a guard picks via "No barcode" → catalog: it reuses the existing
1218	   *  mapping so the receipt rolls into the same stock row. Excludes the
1219	   *  synthetic `catalog_*` placeholders. */
1220	  primary_barcode?: string | null;
1221	};
