/**
 * Single-row catalog read with live-computed `has_barcode` and
 * `primary_barcode` — same shape as `listCanonicalProducts`. Used by the
 * field-app's JIT verification on catalog pick. Site-scoped so a
 * mis-typed productId from another site returns null rather than the
 * wrong product.
 */
export async function findCanonicalProductFull(
  siteId: string,
  productId: string,
): Promise<CanonicalProduct | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${CANONICAL_PRODUCT_COLUMNS}
      FROM canonical_products cp
      WHERE cp.site_id = ? AND cp.product_id = ?
      LIMIT 1
    `,
    args: [siteId, productId],
  });
  return (result.rows[0] as CanonicalProduct | undefined) ?? null;
}

export async function findCanonicalProductByName(
  siteId: string,
  name: string,
): Promise<CanonicalProduct | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT * FROM canonical_products WHERE site_id = ? AND lower(canonical_name) = lower(?) LIMIT 1`,
    args: [siteId, name.trim()],
  });
  return (result.rows[0] as CanonicalProduct | undefined) ?? null;
}

// `has_barcode` is computed from product_barcodes so the field-app's
// register-new-barcode flow can hide products that are already taken
// (one-barcode-per-product rule, for now). `primary_barcode` returns the
// most-recently learned real barcode so the no-barcode pick flow can
// reuse it instead of falling back to a synthetic `catalog_*` id.
const CANONICAL_PRODUCT_COLUMNS = `
  cp.*,
  EXISTS (
    SELECT 1 FROM product_barcodes pb
    WHERE pb.product_id = cp.product_id AND pb.site_id = cp.site_id
  ) AS has_barcode,
  (
    SELECT pb2.barcode FROM product_barcodes pb2
    WHERE pb2.product_id = cp.product_id
      AND pb2.site_id = cp.site_id
      AND pb2.barcode NOT LIKE 'catalog\\_%' ESCAPE '\\'
    ORDER BY pb2.learned_at DESC
    LIMIT 1
  ) AS primary_barcode
`;

export async function listCanonicalProducts(
  siteId: string,
): Promise<CanonicalProduct[]> {
  const db = await getDb();
