    sql: `SELECT ${CANONICAL_PRODUCT_COLUMNS} FROM canonical_products cp WHERE cp.site_id = ? ORDER BY cp.canonical_name`,
    args: [siteId],
  });
  return result.rows as CanonicalProduct[];
}

