if (pathname === "/api/inventory/corrections" && method === "POST") {
  const auth = await authenticate(req, res);
  if (!auth) return true;
  const body = await readBodyJson(req);
  const id = asString(body.id);
  const barcode = asString(body.barcode);
  const newQty = asNumber(body.new_qty);
  if (!id || !barcode || newQty === null) {
    const missing: string[] = [];
    if (!id) missing.push("id");
    if (!barcode) missing.push("barcode");
    if (newQty === null) missing.push("new_qty (numeric)");
    badRequest(res, `Cannot record stock correction — missing or invalid: ${missing.join(", ")}`);
    return true;
  }

  const productName = asString(body.product_name) ?? "Unknown";
  const newExpiry = asString(body.new_expiry);
  // Per-pack expiries: ignore non-string entries and stale data; expect
  // YYYY-MM-DD. Empty array → null so the column stays clean.
  const rawExpiries = Array.isArray(body.new_expiries) ? body.new_expiries : null;
  const newExpiries = rawExpiries
    ? rawExpiries
        .map((v) => asString(v))
        .filter((s): s is string => s !== null && /^\d{4}-\d{2}-\d{2}$/.test(s))
    : null;
  const result = await insertStockCorrection({
    id,
    siteId: auth.siteId,
    barcode,
    productName,
    oldQty: asNumber(body.old_qty),
    newQty,
    oldExpiry: asString(body.old_expiry),
    newExpiry,
    newExpiries: newExpiries && newExpiries.length > 0 ? newExpiries : null,
    deviceId: auth.deviceId,
    guardId: auth.guardId,
    guardName: auth.guardName,
    correctedAt: isoOrNow(body.corrected_at),
  });

  if (result.inserted) {
    await ensureStockRow({
      siteId: auth.siteId,
      barcode,
      fallbackName: productName,
    });

    // The field-app sends either:
    //   - lots: [{qty, expiry_date}]  (new batch model)
    //   - new_expiries: [DATE]         (legacy per-pack; one date per unit)
    //   - new_expiry: DATE             (legacy single)
    // Convert all three shapes to a unified replaceLots payload.
    const rawLots = Array.isArray(body.lots) ? body.lots : null;
    let lotsPayload: LotSummary[];
    if (rawLots) {
      lotsPayload = rawLots
        .map((l) => {
          const expiry = asString((l as Record<string, unknown>).expiry_date);
          const lotQty = asNumber((l as Record<string, unknown>).qty);
          if (lotQty === null || lotQty <= 0) return null;
          return { expiry_date: expiry, qty: lotQty } as LotSummary;
        })
        .filter((l): l is LotSummary => l !== null);
    } else if (newExpiries && newExpiries.length > 0) {
      // Legacy per-pack: collapse identical dates into a single lot.
      const merged = new Map<string, number>();
      for (const d of newExpiries) merged.set(d, (merged.get(d) ?? 0) + 1);
      lotsPayload = Array.from(merged.entries()).map(([d, q]) => ({
        expiry_date: d,
        qty: q,
      }));
    } else {
      lotsPayload = newQty > 0 ? [{ expiry_date: newExpiry ?? null, qty: newQty }] : [];
    }

    // Defensive: clamp to newQty so a malformed lots array (sums to
    // a different total) doesn't quietly disagree with the audit
    // row's new_qty.
    const total = lotsPayload.reduce((s, l) => s + l.qty, 0);
    if (total !== newQty && lotsPayload.length > 0 && total > 0) {
      const scale = newQty / total;
      lotsPayload = lotsPayload.map((l) => ({
        expiry_date: l.expiry_date,
        qty: Math.round(l.qty * scale),
      }));
    }
    await replaceLots({
      siteId: auth.siteId,
      barcode,
      lots: lotsPayload,
