    remote.map((r) => ({
      barcode: r.barcode,
      name: r.name,
      category: r.category,
      unit: r.unit,
      pack_size: r.pack_size != null ? Number(r.pack_size) : null,
      on_hand: Number(r.on_hand),
      threshold: Number(r.threshold),
    })),
  );
  for (const r of remote) {
    await replaceLotsLocal(
