  if (!row) return false;
  const a = [...batches]
    .map((b) => `${b.expiry ?? ''}@${b.qty}`)
    .sort()
    .join('|');
  const b = [...originalBatches]
    .map((b) => `${b.expiry ?? ''}@${b.qty}`)
    .sort()
    .join('|');
  return a !== b;
}, [row, batches, originalBatches]);

const packDisplay = row && row.pack_size != null && row.pack_size !== 1 && row.unit
