1910	// ───────────────────────── Catalog ─────────────────────────
1911	
1912	function CatalogTab() {
1913	  const queryClient = useQueryClient();
1914	  const productsQuery = useQuery({ queryKey: ["inv-canonical"], queryFn: listCanonicalProducts });
1915	  const products = productsQuery.data?.data?.products ?? [];
1916	  const [showForm, setShowForm] = useState(false);
1917	  const [draft, setDraft] = useState({ canonical_name: "", category: "Grocery", hsn_code: "", unit: "pcs", pack_size: 1 });
1918	  const [filter, setFilter] = useState("");
1919	
1920	  const filtered = useMemo(() => {
1921	    const q = filter.trim().toLowerCase();
1922	    if (!q) return products;
1923	    return products.filter((p) =>
1924	      p.canonical_name.toLowerCase().includes(q) ||
1925	      (p.category ?? "").toLowerCase().includes(q) ||
1926	      (p.hsn_code ?? "").toLowerCase().includes(q),
1927	    );
1928	  }, [products, filter]);
1929	
1930	  const createMutation = useMutation({
1931	    mutationFn: () => createCanonicalProduct({
1932	      canonical_name: draft.canonical_name,
1933	      category: draft.category || undefined,
1934	      hsn_code: draft.hsn_code || undefined,
1935	      unit: draft.unit,
1936	      pack_size: draft.pack_size,
1937	    }),
1938	    onSuccess: (res) => {
1939	      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Create failed")); return; }
1940	      toastSuccess("Product created");
1941	      setShowForm(false);
1942	      setDraft({ canonical_name: "", category: "Grocery", hsn_code: "", unit: "pcs", pack_size: 1 });
1943	      void queryClient.invalidateQueries({ queryKey: ["inv-canonical"] });
1944	    },
1945	    onError: (err) => toastError(err, "Create failed"),
1946	  });
1947	
1948	  return (
1949	    <div>
1950	      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, gap: 10 }}>
1951	        <input
1952	          type="text"
1953	          placeholder="Filter by name, category, HSN…"
1954	          value={filter}
1955	          onChange={(e) => setFilter(e.target.value)}
1956	          style={{ ...input, flex: 1, maxWidth: 360 }}
1957	        />
1958	        <div style={{ display: "flex", gap: 8 }}>
1959	          <button type="button" onClick={() => void productsQuery.refetch()} style={ghostBtn}>
1960	            <RefreshCw size={14} /> Refresh
1961	          </button>
1962	          <button
1963	            type="button"
1964	            style={ghostBtn}
1965	            onClick={() => {
1966	              if (confirm(
1967	                "Drop every learned bill-name → product mapping for this site?\n\n" +
1968	                "Standard products and barcode mappings stay. This only clears\n" +
1969	                "the alias cache that auto-fills bill upload suggestions. Use\n" +
1970	                "this if upload suggestions have been pointing to the wrong\n" +
1971	                "products.",
1972	              )) {
1973	                void clearAliases().then((res) => {
1974	                  if (res.ok) toastSuccess(`Cleared ${res.data.deleted} alias(es)`);
1975	                  else toastError(errorMessage((res.data as { error?: string }).error, "Clear failed"));
1976	                });
1977	              }
1978	            }}
1979	          >
1980	            Clear learned aliases
1981	          </button>
1982	          <button type="button" className="primary-button" onClick={() => setShowForm(true)}>
1983	            <Plus size={14} /> New product
1984	          </button>
1985	        </div>
1986	      </div>
1987	
1988	      {showForm && (
1989	        <div style={{ border: "1px solid var(--line)", borderRadius: 10, padding: 14, marginBottom: 12 }}>
1990	          <div style={{ display: "grid", gap: 8, gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr" }}>
1991	            <FieldLabel label="Standard name">
1992	              <input type="text" value={draft.canonical_name} onChange={(e) => setDraft({ ...draft, canonical_name: e.target.value })} style={input} />
1993	            </FieldLabel>
1994	            <FieldLabel label="Category">
1995	              <CategoryCombobox value={draft.category} catalog={products} onChange={(v) => setDraft({ ...draft, category: v })} />
1996	            </FieldLabel>
1997	            <FieldLabel label="HSN">
1998	              <input type="text" value={draft.hsn_code} onChange={(e) => setDraft({ ...draft, hsn_code: e.target.value })} style={input} />
1999	            </FieldLabel>
2000	            <FieldLabel label="Unit">
