import { getDb, now } from './database';

export type Product = {
  barcode: string;
  name: string;
  category: string | null;
  unit: string | null;
  pack_size: number | null;
  dispense_mode: 'pack' | 'divisible';
  updated_at: number;
};

export async function findProduct(barcode: string): Promise<Product | null> {
  const db = await getDb();
  const row = await db.getFirstAsync<Product>(
    'SELECT * FROM products WHERE barcode = ?',
    [barcode]
  );
  return row ?? null;
}

export async function upsertProduct(p: Omit<Product, 'updated_at'>): Promise<Product> {
  const db = await getDb();
  const ts = now();
  await db.runAsync(
    `INSERT INTO products (barcode, name, category, unit, pack_size, dispense_mode, updated_at)
     VALUES (?, ?, ?, ?, ?, COALESCE(?, 'pack'), ?)
     ON CONFLICT(barcode) DO UPDATE SET
       name=excluded.name,
       category=excluded.category,
       unit=excluded.unit,
       pack_size=excluded.pack_size,
       dispense_mode=excluded.dispense_mode,
       updated_at=excluded.updated_at`,
    [p.barcode, p.name, p.category, p.unit, p.pack_size, p.dispense_mode ?? null, ts]
  );
  return { ...p, updated_at: ts };
}

export async function listProducts(limit = 200): Promise<Product[]> {
  const db = await getDb();
  return db.getAllAsync<Product>(
    'SELECT * FROM products ORDER BY updated_at DESC LIMIT ?',
    [limit]
  );
}

