      barcode,
      name: trimmedName,
      category,
      unit,
      packSize: parsedPackSize,
    });
    flushOnce().catch(() => {});
    haptic.success();
    navigation.push('Receiving', {
      barcode,
      packSize: parsedPackSize ?? undefined,
    });
  }
} finally {

