// ───────────────────────── Stock ─────────────────────────

function StockTab() {
  const stockQuery = useQuery({
    queryKey: ["inv-stock-snapshot"],
    queryFn: listStockSnapshot,
    staleTime: 30_000,
  });
  const rows: StockSnapshotRow[] = stockQuery.data?.data?.rows ?? [];
  const [filter, setFilter] = useState("");

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    if (!q) return rows;
    return rows.filter(
      (r) =>
        r.canonical_name.toLowerCase().includes(q) ||
        (r.category ?? "").toLowerCase().includes(q) ||
        (r.barcodes ?? "").toLowerCase().includes(q),
    );
  }, [rows, filter]);

  const syncMutation = useMutation({
    mutationFn: syncStockSheet,
    onSuccess: (res) => {
      if (!res.ok) {
        toastError(errorMessage((res.data as { error?: string }).error, "Sync failed"));
        return;
      }
      toastSuccess("Stock pushed to Google Sheet");
    },
    onError: (err) => toastError(err, "Sync failed"),
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, gap: 10 }}>
        <input
          type="text"
          placeholder="Filter by name, category, barcode…"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ ...input, flex: 1, maxWidth: 360 }}
        />
        <div style={{ display: "flex", gap: 8 }}>
          <button type="button" onClick={() => void stockQuery.refetch()} style={ghostBtn}>
            <RefreshCw size={14} /> Refresh
          </button>
          <button
            type="button"
            style={ghostBtn}
            disabled={syncMutation.isPending}
            onClick={() => syncMutation.mutate()}
          >
            <Upload size={14} /> {syncMutation.isPending ? "Syncing…" : "Sync to Sheet"}
          </button>
        </div>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "var(--muted)" }}>
              <th style={th}>Product Name</th>
              <th style={th}>Category</th>
              <th style={th}>Unit</th>
              <th style={th}>Unit Value</th>
              <th style={th}>Price</th>
              <th style={th}>Barcode</th>
              <th style={th}>No. of units</th>
              <th style={th}>Expiry dates</th>
            </tr>
          </thead>
          <tbody>
            {stockQuery.isLoading && (
              <tr>
                <td style={td} colSpan={8}>Loading…</td>
              </tr>
            )}
            {!stockQuery.isLoading && filtered.length === 0 && (
              <tr>
                <td style={{ ...td, color: "var(--muted)" }} colSpan={8}>
                  No stock yet. Items appear once they're received via the field-app.
                </td>
              </tr>
            )}
            {filtered.map((r, i) => (
              <tr key={`${r.canonical_name}-${i}`} style={{ borderTop: "1px solid var(--line)" }}>
                <td style={td}>{r.canonical_name}</td>
                <td style={td}>{r.category ?? "—"}</td>
                <td style={td}>{r.unit}</td>
                <td style={td}>{r.pack_size}</td>
                <td style={td}>{r.last_price != null ? r.last_price.toString() : "—"}</td>
                <td style={{ ...td, fontFamily: "monospace", fontSize: 12 }}>{r.barcodes ?? "—"}</td>
                <td style={td}>{r.on_hand}</td>
                <td style={{ ...td, color: r.expiry_dates ? "inherit" : "var(--muted)" }}>
                  {r.expiry_dates ?? "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

