/**
 * Expiry display helpers for the admin dashboard. Mirrors the field-app's
 * `src/utils/expiry.ts` so guards and admins see the same date format
 * ("15 Aug 2026"), relative-time wording ("in 3 months"), and urgency
 * buckets (red / amber / neutral).
 */

export type ExpiryUrgency = 'expired' | 'soon' | 'ok' | 'none';

const MONTHS_SHORT = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function parseISO(iso: string | null | undefined): Date | null {
  if (!iso) return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return null;
  const [, y, mo, d] = m;
  return new Date(Number(y), Number(mo) - 1, Number(d));
}

function startOfToday(): Date {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
}

export function formatExpiry(iso: string | null | undefined): string {
  const d = parseISO(iso ?? null);
  if (!d) return 'No expiry';
  return `${d.getDate()} ${MONTHS_SHORT[d.getMonth()]} ${d.getFullYear()}`;
}

export function daysUntilExpiry(iso: string | null | undefined): number | null {
  const d = parseISO(iso ?? null);
  if (!d) return null;
  return Math.round((d.getTime() - startOfToday().getTime()) / MS_PER_DAY);
}

export function expiryUrgency(iso: string | null | undefined): ExpiryUrgency {
  const days = daysUntilExpiry(iso);
  if (days === null) return 'none';
  if (days < 0) return 'expired';
  if (days <= 30) return 'soon';
  return 'ok';
}

export function relativeExpiry(iso: string | null | undefined): string | null {
  const days = daysUntilExpiry(iso);
  if (days === null) return null;
  if (days === 0) return 'expires today';
  if (days === 1) return 'tomorrow';
  if (days === -1) return 'yesterday';
  if (days > 0) {
    if (days < 14) return `in ${days} days`;
    if (days < 60) return `in ${Math.round(days / 7)} weeks`;
    if (days < 365 * 2) return `in ${Math.round(days / 30)} months`;
    return `in ${Math.round(days / 365)} years`;
  }
  const abs = -days;
  if (abs < 14) return `${abs} days ago`;
  if (abs < 60) return `${Math.round(abs / 7)} weeks ago`;
  if (abs < 365 * 2) return `${Math.round(abs / 30)} months ago`;
  return `${Math.round(abs / 365)} years ago`;
}

/** CSS colors (fg/bg/border) for each urgency bucket. Uses simple hex
 *  rather than CSS variables because the dashboard theme tokens are
 *  light/neutral-only — no warn/error containers yet. Light-mode tuned. */
export function urgencyColors(urgency: ExpiryUrgency): {
  fg: string;
  bg: string;
  border: string;
} {
  switch (urgency) {
    case 'expired':
      return { fg: '#7F1D1D', bg: '#FEE2E2', border: '#FCA5A5' };
    case 'soon':
      return { fg: '#7C2D12', bg: '#FEF3C7', border: '#FCD34D' };
    case 'ok':
      return { fg: '#1F2937', bg: '#F3F4F6', border: '#D1D5DB' };
    case 'none':
    default:
      return { fg: '#6B7280', bg: 'transparent', border: '#D1D5DB' };
  }
}

