// ───────────────────────── Stock ─────────────────────────

/**
 * Renders the per-batch breakdown as urgency-colored chips. Each chip
 * shows "qty × DATE" with the relative-time hint underneath; red for
 * expired, amber for ≤30 days, neutral otherwise. Falls back to the
 * compact server string for legacy rows with no lot data.
 */
function ExpiryCell({ row }: { row: StockSnapshotRow }) {
  const lots = row.lots ?? [];
  if (lots.length === 0) {
    return (
      <span style={{ color: row.expiry_dates ? "inherit" : "var(--muted)" }}>
        {row.expiry_dates ?? "—"}
      </span>
    );
  }
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
      {lots.map((lot, i) => {
        const urgency = expiryUrgency(lot.expiry_date);
        const colors = urgencyColors(urgency);
        const rel = relativeExpiry(lot.expiry_date);
        return (
          <span
            key={`${lot.expiry_date ?? "none"}-${i}`}
            title={rel ?? undefined}
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              padding: "3px 8px",
              borderRadius: 999,
              border: `1px solid ${colors.border}`,
              background: colors.bg,
              color: colors.fg,
              fontSize: 12,
              lineHeight: 1.3,
              whiteSpace: "nowrap",
            }}
          >
            <strong style={{ fontWeight: 600 }}>{lot.qty}</strong>
            <span style={{ opacity: 0.5 }}>×</span>
            <span>{formatExpiry(lot.expiry_date)}</span>
            {rel ? (
              <span style={{ opacity: 0.7, fontSize: 11 }}>· {rel}</span>
            ) : null}
          </span>
        );
      })}
    </div>
  );
}

